from donnees import C,E

CHAPITRES=[]
CHAPITRES.append(C(18,'Lumière : propagation et distances','Voir loin, est-ce voir le passé ?',
['Distinguer source primaire, diffusion et réception.','Exploiter le modèle du rayon et construire une ombre.','Relier distance, durée et vitesse de la lumière.'],['Trajets, vitesse moyenne et organisation du Système solaire.'],[
('De la source à l’œil',r'Une source primaire émet de la lumière ; un objet diffusant renvoie dans plusieurs directions une partie de la lumière reçue. Pour voir un objet, de la lumière issue de cet objet doit entrer dans l’œil. L’œil ne projette pas un rayon pour « toucher » l’objet. Un écran peut recevoir de la lumière sans la détecter comme un capteur électronique ; on précise le rôle de chaque système.','c18-ombre','Pour une source ponctuelle, les rayons limites construisent une zone d’ombre derrière un objet opaque. Schéma géométrique simplifié.'),
('Un modèle de propagation',r'Dans le vide et dans un milieu transparent homogène comme l’air calme à l’échelle du dispositif, la lumière se propage en ligne droite. Un rayon est une ligne orientée représentant sa direction et son sens. Il ne dessine pas la largeur réelle d’un faisceau. Un objet opaque peut intercepter certains trajets et créer une ombre. Les sources étendues peuvent aussi produire une pénombre.','',''),
('Une vitesse immense mais finie',r'Dans le vide, $c=299\,792\,458\unite{m/s}$ exactement ; pour nos calculs, $c\approx300\,000\unite{km/s}$. On utilise $d=c\Delta t$ ou $\Delta t=d/c$ en gardant les unités cohérentes. Dans un matériau transparent, la lumière peut se propager moins vite que dans le vide. Une distance astronomique peut donc correspondre à un délai observable, même si les délais du laboratoire sont minuscules.','c18-trajet','Un trajet aller-retour mesure une distance totale égale à deux fois la séparation des objets.'),
('Année-lumière et observation',r'Une année-lumière est la distance parcourue par la lumière dans le vide en un an : environ $9{,}46\times10^{12}\unite{km}$. Une étoile à quatre années-lumière est observée avec environ quatre ans de retard sur l’émission. Ce délai ne signifie pas qu’elle est forcément éteinte aujourd’hui. Les observations du Soleil ou d’une source intense exigent des moyens spécialisés ; aucun regard direct n’est proposé dans ce livre.','','')],
r'Pour une distance Terre-Soleil arrondie à $150$ millions de kilomètres, on calcule : \[\Delta t=\dfrac{150\,000\,000}{300\,000}=500\unite s,\] soit $8\unite{min}\,20\unite s$. On observe donc le Soleil avec ce délai approximatif. Le calcul utilise une distance et une vitesse arrondies, sans prédire toutes les variations orbitales.',
r'\textbf{Question.} Le modèle rectiligne prédit-il l’ombre ? Avec une petite lampe scolaire, un objet opaque et un écran, tracer d’abord les rayons limites sur un schéma. Mesurer les distances relatives puis comparer la prévision à l’ombre observée. Déplacer l’écran et décrire l’effet. Une source étendue donne des bords moins nets : discuter la limite de l’approximation ponctuelle. \textbf{À rendre :} rayons orientés, zones éclairées et zone d’ombre. Ni laser dirigé vers les yeux ni observation du Soleil.',
['Un objet est vu lorsque sa lumière entre dans l’œil.','Un rayon est un modèle orienté de propagation.','L’ombre résulte de trajets interceptés par un objet opaque.','La vitesse de la lumière dans le vide est finie.','L’année-lumière est une unité de distance.'],
r'Pour un signal réfléchi, la durée mesurée correspond souvent à l’aller et au retour : ne pas attribuer tout $c\Delta t$ à la seule distance source-obstacle.',[
E('Source ou diffuseur','Une lampe allumée et une feuille éclairée ont-elles le même rôle lumineux ?@@Lequel est une source primaire ?','Non : la lampe émet sa lumière, la feuille diffuse celle qu’elle reçoit.@@La lampe allumée.'),
E('Le bon sens','Dans un dessin de vision d’une feuille, orienter le rayon entre feuille et œil.@@L’œil émet-il ce rayon pour voir ?','De la feuille vers l’œil.@@Non : la vision exige la réception de lumière.'),
E('La trajectoire','Comment se propage la lumière dans un milieu transparent homogène, selon le modèle ?@@Un rayon possède-t-il un sens ?','En ligne droite.@@Oui : une flèche indique le sens de propagation.'),
E('Une grande vitesse',r'Quelle valeur arrondie de c utilise-t-on en km/s ?@@Est-ce une vitesse infinie ?',r'$300\,000\unite{km/s}$.@@Non : la propagation sur une distance finie nécessite une durée non nulle.'),
E('La zone d’ombre','Qu’est-ce qui crée une ombre derrière un objet opaque ?@@Un milieu transparent crée-t-il toujours la même ombre ?','L’objet intercepte une partie des trajets lumineux issus de la source.@@Non : transmission, absorption, diffusion et géométrie du milieu changent la situation.'),
E('Un trajet en une seconde',r'Avec $c=300\,000\unite{km/s}$, quelle distance en $2\unite s$ ?@@Et en $0{,}10\unite s$ ?',r'$600\,000\unite{km}$.@@$30\,000\unite{km}$.',calculs=[('300000*2',600000),('300000*.1',30000)]),
E('Une durée solaire',r'Calculer le délai sur $150$ millions de kilomètres avec la vitesse du cours.@@Exprimer en minutes et secondes.',r'$500\unite s$.@@$8\unite{min}\,20\unite s$.',calculs=[('150000000/300000',500)]),
E('Un aller simple lunaire',r'Pour $384\,000\unite{km}$, calculer la durée aller de la lumière.@@Calculer l’aller-retour idéal.',r'$384\,000/300\,000=1{,}28\unite s$.@@$2{,}56\unite s$ en négligeant les mouvements pendant le trajet.',calculs=[('384000/300000',1.28),('2*384000/300000',2.56)]),
E('Une étoile',r'Une étoile est située à 12 années-lumière. Quel retard approximatif a sa lumière ?@@Cela donne-t-il son état actuel ?','Environ 12 ans.@@Non : on observe l’état correspondant à la lumière partie environ 12 ans auparavant.'),
E('Une unité à convertir',r'On prend $1\unite{al}=9{,}46\times10^{12}\unite{km}$. Quelle distance pour 2 al ?@@Quelle durée de propagation dans le vide ?',r'$1{,}892\times10^{13}\unite{km}$.@@Deux ans, par définition de l’année-lumière.',calculs=[('2*9.46e12',1.892e13)]),
E('Une mesure réfléchie',r'Un signal lumineux revient après $0{,}004\unite s$. Avec $c=300\,000\unite{km/s}$, calculer la distance de l’obstacle.@@Pourquoi diviser par deux ?',r'$d=c\Delta t/2=600\unite{km}$.@@La lumière a parcouru l’aller et le retour pendant la durée mesurée.',calculs=[('300000*.004/2',600)]),
E('Une ombre qui grandit','Avec une petite source et un objet fixes, on éloigne l’écran derrière l’objet. L’ombre géométrique grandit-elle dans le modèle ?@@Quelle construction justifie la réponse ?','Oui dans cette configuration de source ponctuelle divergente.@@Prolonger les rayons passant par la source et les bords de l’objet jusqu’aux deux positions de l’écran.'),
E('Le rayon invisible','Dans l’air très propre, on voit une tache sur l’écran mais pas forcément le trajet du faisceau de côté. Pourquoi ?@@Que change une légère diffusion ?',r'Peu de lumière est alors renvoyée latéralement vers l’œil ; le rayon dessiné n’est pas une trace matérielle visible.@@Des particules diffusent une partie de la lumière vers l’œil et peuvent rendre le trajet perceptible, selon le dispositif.'),
E('Deux échelles',r'Un laboratoire mesure une distance de $3\unite m$. Avec $c\approx3\times10^8\unite{m/s}$, calculer le délai aller.@@Pourquoi un chronomètre manuel ne convient-il pas ?',r'$\Delta t=3/(3\times10^8)=10^{-8}\unite s$.@@Ce délai est bien inférieur à la résolution et au temps de réaction d’un chronométrage manuel.',calculs=[('3/3e8',1e-8)]),
E('Une conclusion médiatique','Un titre dit « Cette étoile est loin, donc elle est déjà morte ». Est-ce démontré ?@@Quelle conclusion est justifiée par la distance seule ?','Non : son évolution dépend notamment de sa nature et de son histoire, pas uniquement du délai lumineux.@@On reçoit une information ancienne d’un temps approximativement égal à la distance en années-lumière, exprimé en années.')],
E('Le miroir spatial',r'Un dispositif reçoit un écho lumineux après $2{,}4\unite s$. Estimer la distance au réflecteur avec $c=300\,000\unite{km/s}$.@@Un élève annonce 720 000 km. Expliquer son erreur.@@Si le délai augmente, quelle conclusion est possible sous les mêmes hypothèses ?',r'$d=300\,000\times2{,}4/2=360\,000\unite{km}$.@@720 000 km est la longueur totale aller-retour, pas la séparation.@@La distance augmente si le trajet et les autres délais du dispositif sont comparables. Un retard instrumental variable doit être exclu.',calculs=[('300000*2.4/2',360000)])))

CHAPITRES.append(C(19,'Le son : fréquence, propagation et écho','Pourquoi voit-on l’éclair avant d’entendre le tonnerre ?',
['Décrire source vibrante et milieu de propagation.','Distinguer fréquence, hauteur et niveau sonore.','Calculer une distance avec un délai de propagation ou un écho.'],['Distance, durée, vitesse et lecture de graphiques.'],[
('Un son a besoin d’un milieu',r'Une source sonore vibre et perturbe un milieu matériel. La perturbation se transmet dans un gaz, un liquide ou un solide ; le son ne se propage pas dans le vide. Les particules du milieu oscillent localement : elles ne voyagent pas toutes de la source à l’oreille. Dans l’air vers $20\,^{\circ}\mathrm C$, on utilise ici $v\approx340\unite{m/s}$. La valeur dépend du milieu et de la température.','c19-signaux','Deux signaux périodiques de même amplitude schématique : celui qui présente davantage de motifs par seconde a une fréquence plus élevée.'),
('Fréquence et hauteur',r'La fréquence $f$ indique le nombre de motifs périodiques par seconde, en hertz (Hz). Une fréquence plus élevée correspond à un son plus aigu pour les sons simples comparés. L’audition humaine jeune couvre approximativement 20 Hz à 20 000 Hz, avec de fortes variations individuelles. En dessous : infrasons ; au-dessus : ultrasons. Ces mots ne désignent pas des niveaux sonores plus ou moins forts.','',''),
('Distance et temps de propagation',r'Pour un trajet simple, $d=v\Delta t$. Pour un écho, le son parcourt l’aller et le retour : $2d=v\Delta t$. Le délai entre éclair et tonnerre donne une estimation de distance parce que la lumière arrive bien plus vite que le son. On suppose les deux émissions proches dans le temps et on néglige le délai lumineux pour cette estimation.','c19-echo','Un émetteur-récepteur chronomètre le retour ; la distance parcourue par le signal est 2d.'),
('Préserver son audition',r'Le niveau sonore, souvent exprimé en décibels (dB), décrit une autre propriété que la fréquence. Le risque auditif dépend notamment du niveau, de la durée et de la répétition des expositions. Une gêne n’est pas un instrument de mesure et l’absence de douleur ne prouve pas l’absence de risque. Réduire le niveau, s’éloigner et limiter la durée sont des moyens de prévention. Aucun essai du livre ne cherche un niveau fort.','','')],
r'Un écho revient $0{,}40\unite s$ après l’émission dans l’air. Le trajet total vaut $340\times0{,}40=136\unite m$. La paroi est à $136/2=68\unite m$. Pour un tonnerre entendu 3 secondes après l’éclair, la distance estimée est au contraire $340\times3=1\,020\unite m$ : on ne divise pas par deux, car c’est un trajet simple.',
r'\textbf{Question.} Comment distinguer hauteur et niveau ? Le professeur fournit deux enregistrements modérés ou des tracés, l’un avec davantage de motifs sur une même durée, l’autre avec une amplitude différente. Comparer sans augmenter le volume. Compter les motifs sur une durée donnée et calculer une fréquence. \textbf{Étude de documents :} comparer un délai de tonnerre à un délai d’écho ; dessiner le trajet avant de choisir la formule. \textbf{À rendre :} fréquence, description de la hauteur et distinction avec le niveau.',
['Le son nécessite un milieu matériel ; il ne traverse pas le vide.','Une source sonore met un milieu en vibration.','La fréquence en Hz caractérise la répétition temporelle.','La hauteur et le niveau sonore sont deux propriétés différentes.','Un écho correspond à un trajet aller-retour.'],
r'Ne pas dire « ultrason = son très fort ». Un ultrason est défini par sa fréquence supérieure à la plage audible humaine usuelle.',[
E('Le milieu','Le son peut-il se propager dans le vide ?@@Peut-il traverser de l’eau ?','Non, il nécessite un milieu matériel.@@Oui, avec une vitesse qui diffère de celle dans l’air.'),
E('La source','Quelle propriété mécanique permet à une source de produire un son ?@@Les molécules d’air vont-elles toutes jusqu’à l’oreille ?','Une vibration transmise au milieu.@@Non : elles oscillent localement et transmettent la perturbation.'),
E('L’unité','Quelle unité pour la fréquence ?@@Que signifie une fréquence de 100 Hz pour un signal périodique ?','Le hertz, Hz.@@Cent motifs ou cycles par seconde.'),
E('Trois domaines',r'Classer $10\unite{Hz}$, $1\,000\unite{Hz}$ et $40\unite{kHz}$.@@Cette classification concerne-t-elle le niveau ?','Infrason, son dans la plage audible humaine usuelle, ultrason.@@Non : elle concerne la fréquence.'),
E('Le plus aigu','Comparer deux sons simples de 200 et 800 Hz. Lequel est le plus aigu ?@@Est-il nécessairement plus fort ?','Celui de 800 Hz.@@Non : la fréquence ne donne pas à elle seule le niveau sonore.'),
E('Une distance simple',r'Dans l’air, un son met $2\unite s$ pour atteindre un auditeur. Calculer la distance avec $340\unite{m/s}$.@@S’agit-il d’un aller-retour ?',r'$d=340\times2=680\unite m$.@@Non, c’est un trajet simple de la source au récepteur.',calculs=[('340*2',680)]),
E('Un écho',r'Un écho revient après $0{,}50\unite s$. Calculer la distance à la paroi.@@Quelle longueur a parcourue le son ?',r'$d=340\times0{,}50/2=85\unite m$.@@$170\unite m$ au total.',calculs=[('340*.5/2',85),('340*.5',170)]),
E('Compter des motifs',r'Un tracé comporte $8$ motifs en $0{,}020\unite s$. Calculer f.@@Comparer à 200 Hz.',r'$f=8/0{,}020=400\unite{Hz}$.@@Le son simple de 400 Hz est plus aigu, à conditions de comparaison adaptées.',calculs=[('8/.02',400)]),
E('Le tonnerre',r'Un délai de $5\unite s$ sépare éclair et tonnerre. Estimer la distance.@@Quelle durée a-t-on négligée ?',r'$d\approx340\times5=1\,700\unite m$.@@Le temps de propagation de la lumière, très faible devant celui du son sur cette distance.',calculs=[('340*5',1700)]),
E('Dans l’eau',r'Un sonar reçoit un écho après $0{,}20\unite s$. On fournit $v=1\,500\unite{m/s}$ dans l’eau. Trouver la profondeur.@@Pourquoi ne pas utiliser 340 m/s ?',r'$d=1\,500\times0{,}20/2=150\unite m$.@@Le milieu est l’eau ; la vitesse fournie est adaptée à ce milieu.',calculs=[('1500*.2/2',150)]),
E('Un signal plus grand','Deux tracés montrent la même période, mais des amplitudes différentes sur la même échelle. Leur fréquence diffère-t-elle ?@@Que peut-on dire de leur hauteur si ce sont des sons simples ?','Non : la répétition temporelle est identique.@@La hauteur est identique ; les amplitudes et niveaux peuvent différer selon la mesure et le dispositif.'),
E('Une information incomplète','Un document indique un niveau de 80 dB sans durée ni conditions. Peut-on conclure seul sur tout le risque auditif ?@@Quels renseignements ajouter ?','Non : la durée et la répétition comptent aussi, ainsi que les conditions de mesure.@@Durée d’exposition, répétition, position du récepteur et variations de niveau ; on ne réalise pas de test fort pour vérifier.'),
E('Deux trajets confondus',r'Un élève calcule $340\times0{,}30=102\unite m$ comme distance d’une paroi pour un écho. Corriger.@@Le même produit serait-il pertinent pour un trajet simple de 0,30 s ?',r'Pour l’écho, la distance de la paroi est $102/2=51\unite m$.@@Oui : sur un trajet simple, $d=v\Delta t=102\unite m$.',calculs=[('340*.3/2',51)]),
E('Un délai instrumental',r'Un dispositif ajoute $0{,}010\unite s$ au délai d’écho affiché de $0{,}210\unite s$. Calculer la distance dans l’air après correction.@@Pourquoi corriger avant de diviser par deux ?',r'Délai de propagation : $0{,}200\unite s$ ; $d=340\times0{,}200/2=34\unite m$.@@Le retard électronique ne correspond pas à un trajet du son et doit être retiré du temps total d’abord.',calculs=[('340*(.210-.010)/2',34)]),
E('Un contrôle de vraisemblance',r'Un capteur dans l’air annonce un obstacle à 3,4 m avec un écho de 2 s. Est-ce cohérent avec 340 m/s ?@@Quel délai attendrait-on pour 3,4 m ?',r'Non : 2 s correspondraient à $340\unite m$ pour un aller-retour.@@$\Delta t=2d/v=6{,}8/340=0{,}020\unite s$. Vérifier l’unité de temps affichée.',calculs=[('2*3.4/340',.02)])],
E('Deux capteurs, deux milieux',r'Un capteur A mesure un écho de $0{,}10\unite s$ dans l’air ; B un écho de même durée dans l’eau. Utiliser respectivement 340 et 1 500 m/s. Calculer les distances.@@Pourquoi un même délai ne donne-t-il pas la même distance ?@@Quelle donnée faut-il toujours annoncer dans un compte rendu ?',r'A : $17\unite m$ ; B : $75\unite m$.@@La vitesse de propagation dépend du milieu.@@Le milieu, la vitesse utilisée et le caractère aller-retour du trajet, ainsi que les éventuels retards instrumentaux.',calculs=[('340*.1/2',17),('1500*.1/2',75)])))

CHAPITRES.append(C(20,'Signaux et information','Comment un signal devient-il un message ?',
['Identifier émetteur, support de propagation et récepteur.','Distinguer information et grandeur physique du signal.','Lire un codage et discuter la qualité d’une mesure.'],['Sources lumineuses et sonores, graphique et proportionnalité.'],[
('Une chaîne de communication',r'Un émetteur produit un signal ; un récepteur le détecte et permet d’en extraire une information grâce à un code ou un traitement. Un signal peut être lumineux, sonore, électrique ou radio. Les ondes radio appartiennent à la famille des rayonnements électromagnétiques : elles ne sont pas des sons et peuvent se propager dans le vide. Le signal est un phénomène physique ; l’information est le sens ou la donnée qu’on lui associe.','c20-chaine','Une communication peut convertir plusieurs fois la nature du signal entre la source du message et son destinataire.'),
('Coder un message',r'Un code établit une correspondance connue entre des signaux et des symboles. Deux états distincts permettent de coder 0 et 1 ; une suite de bits peut ensuite représenter plusieurs symboles. Un signal n’a pas de sens unique sans convention : un voyant rouge peut annoncer une alerte ou un état choisi par le concepteur. Le codage doit préciser les durées, l’ordre des symboles et leur séparation.','',''),
('Mesurer avec un signal',r'Un capteur transforme une grandeur physique en une sortie exploitable. Un étalonnage relie des valeurs connues de la grandeur aux valeurs du signal. Dans une plage donnée, une relation peut être proportionnelle ou affine, mais ce n’est pas automatique. Un signal analogique varie continûment dans son modèle ; un traitement numérique utilise des valeurs discrètes. Cette distinction ne signifie pas que le numérique est toujours exact.','c20-signaux','À gauche : variation continue. À droite : états de code 0 ou 1 ; les valeurs et le sens du message dépendent de la convention.'),
('Détecter les limites',r'Bruit, obstacle, distance, mauvaise orientation et perturbations peuvent dégrader la réception. Répéter un message ou ajouter une vérification aide parfois à repérer une erreur, sans la supprimer toujours. Pour une mesure, on contrôle étalonnage, plage, résolution et temps de réponse. Une donnée affichée avec beaucoup de chiffres ne garantit pas une grande exactitude. Expliquer la limite du dispositif fait partie d’une conclusion scientifique.','','')],
r'Un capteur scolaire donne $U=0{,}020\,T+0{,}50$, avec U en V et T en degrés Celsius, entre 0 et 50 °C. Pour $U=1{,}10\unite V$, $T=(1{,}10-0{,}50)/0{,}020=30\,^{\circ}\mathrm C$. Ce calcul utilise l’étalonnage fourni ; il ne permet pas d’extrapoler à une température arbitraire.',
r'\textbf{Mission.} Inventer un code lumineux à deux états pour quatre messages, puis le transmettre à faible distance avec une petite lampe adaptée. Échanger le code avant la transmission. Tester un message, puis introduire sur document une erreur de symbole. Proposer un moyen de détection et discuter sa limite. \textbf{À rendre :} table du code, chronologie des états, chaîne émetteur-récepteur et bilan de fiabilité. Aucun émetteur radio n’est fabriqué et aucune lumière intense n’est utilisée.',
['Le signal est un phénomène physique portant une information codée.','Un récepteur doit disposer d’un code ou d’un traitement.','Les ondes radio ne sont pas des ondes sonores.','Une mesure par capteur exige un étalonnage et une plage d’utilisation.','Les perturbations peuvent modifier le signal et l’information reçue.'],
r'Un affichage numérique de 23,456 °C ne prouve pas que la température est connue au millième de degré : la qualité du capteur et de l’étalonnage limite le résultat.',[
E('Les rôles','Dans une sonnette, identifier un émetteur sonore et un récepteur humain.@@Quelle information peut être transmise ?','L’avertisseur émet ; l’oreille de l’utilisateur reçoit le signal.@@Une demande d’attention ou l’annonce d’une présence, selon la convention.'),
E('Radio et son','Une onde radio est-elle un son très aigu ?@@Peut-elle traverser le vide ?','Non : c’est un rayonnement électromagnétique.@@Oui, contrairement au son qui nécessite un milieu matériel.'),
E('Deux états','Que signifie un code à deux états ?@@Le voyant allumé signifie-t-il partout « danger » ?','Deux valeurs ou catégories distinguables représentent par exemple 0 et 1.@@Non : le sens dépend de la convention annoncée.'),
E('Le capteur','Quel est le rôle d’un capteur ?@@Pourquoi l’étalonner ?','Relier une grandeur physique à un signal exploitable.@@Pour établir ou vérifier la correspondance entre la grandeur et la sortie.'),
E('Une perturbation','Nommer une cause de mauvaise réception lumineuse.@@Et une cause de mauvaise réception sonore ?','Un obstacle, une mauvaise orientation ou un éclairage ambiant gênant.@@Un obstacle, une source de bruit ou une distance trop grande.'),
E('Lire un code','Le code fourni est A = 00, B = 01, C = 10, D = 11. Décoder 01 10 00.@@Pourquoi les espaces sont-ils utiles ?','B C A.@@Ils indiquent les groupes de deux bits et empêchent une lecture ambiguë ; un protocole peut aussi fixer cette longueur.'),
E('Compter des messages','Combien de suites différentes peut-on faire avec deux bits ?@@Donner les suites.','Quatre.@@00, 01, 10 et 11.'),
E('Un étalonnage simple',r'Un capteur donne $U=0{,}10\,x$ avec U en V et x dans son unité. Calculer U pour x = 12.@@Retrouver x pour U = 0,8 V.',r'$U=1{,}2\unite V$.@@$x=0{,}8/0{,}10=8$ dans l’unité de la grandeur donnée.',calculs=[('.1*12',1.2),('.8/.1',8)]),
E('Une sortie affine',r'Pour $U=0{,}020T+0{,}50$, calculer U à 20 °C.@@La relation est-elle proportionnelle entre U et T ?',r'$U=0{,}90\unite V$.@@Non : à $T=0$, U vaut 0,50 V. C’est une relation affine dans le domaine fourni.',calculs=[('.020*20+.50',.9)]),
E('Une valeur reçue',r'Avec l’étalonnage précédent, retrouver T pour $U=1{,}30\unite V$.@@La valeur est-elle dans la plage 0 à 50 °C ?',r'$T=(1{,}30-0{,}50)/0{,}020=40\,^{\circ}\mathrm C$.@@Oui, elle appartient à la plage annoncée.',calculs=[('(1.3-.5)/.02',40)]),
E('Une erreur de bit','Le code de l’exercice 6 est utilisé. B = 01 est reçu 11. Quel message est lu ?@@Le récepteur peut-il détecter l’erreur avec cette seule table ?','D.@@Non : 11 est un code valide. Il faut une information de contrôle supplémentaire pour repérer certains défauts.'),
E('Répéter et comparer','Un message est reçu deux fois : 01 10 puis 01 11. Que montre la comparaison ?@@Permet-elle de savoir quelle version est correcte ?','Au moins une transmission ou lecture est incohérente ; le deuxième groupe diffère.@@Non à elle seule : la répétition détecte ici un désaccord, mais ne désigne pas la bonne version.'),
E('Hors de la plage',r'Un élève utilise $U=0{,}020T+0{,}50$ pour U = 3 V, alors que l’étalonnage vaut de 0 à 50 °C. Quel calcul obtient-il ?@@Pourquoi ne doit-il pas annoncer ce résultat comme une mesure fiable ?',r'$T=(3-0{,}50)/0{,}020=125\,^{\circ}\mathrm C$.@@Ce résultat est hors de la plage validée ; le capteur peut saturer ou changer de comportement. Il faut une autre méthode adaptée.',calculs=[('(3-.5)/.02',125)]),
E('Une résolution fournie',r'Un capteur affiche la température par pas de $0{,}5\,^{\circ}\mathrm C$. Peut-il distinguer à l’affichage 20,1 et 20,2 °C ?@@Cette résolution résume-t-elle toute la qualité de mesure ?','Pas avec cet affichage en pas de 0,5 °C.@@Non : exactitude, étalonnage, temps de réponse et conditions de contact interviennent aussi.'),
E('Analogique ou numérique','Une tension varie continûment puis un convertisseur donne des nombres arrondis. Décrire les deux représentations.@@Les arrondis constituent-ils une erreur humaine ?','La tension est modélisée comme analogique ; la sortie chiffrée est discrète et numérique.@@Non : une résolution limitée fait partie du dispositif. Il faut en tenir compte dans l’interprétation.')],
E('Le protocole du phare','On code quatre messages par deux bits, avec 1 = lampe allumée et 0 = éteinte. Chaque bit dure 1 s. Combien de temps dure un message, hors séparation ?@@Proposer un signal de début pour éviter de confondre silence et 00.@@Pourquoi la seule répétition ne garantit-elle pas une correction parfaite ?','Deux secondes, puisque chaque message comporte deux bits.@@Par exemple un allumage plus long de durée convenue, suivi d’une séparation précise, puis les deux bits. Le récepteur doit connaître cette convention.@@Une même perturbation peut se reproduire, et deux versions différentes ne permettent pas toujours de choisir la bonne. Il faut tester le protocole et discuter ses limites.')))
